c = r"""import React, { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useParams } from 'react-router-dom';
import { fetchJSON, imgUrl } from './services/tmdb';
function Card({ item, type='movie' }) { const href = '/' + type + '/' + item.id; return <a href={href} style={{display:'block',background:'var(--card)',borderRadius:12,padding:8,border:'1px solid var(--border)',textDecoration:'none'}}><img src={imgUrl(item.poster_path,'w300')||'https://via.placeholder.com/300x450?text=No+Poster'} alt={item.title||item.name} style={{width:'100%',borderRadius:8,height:270,objectFit:'cover'}} /><h3 style={{marginTop:8,fontSize:15,color:'var(--text)',fontWeight:600}}>{item.title||item.name}</h3><p style={{fontSize:12,color:'var(--muted)'}}>{(item.release_date||item.first_air_date||'').slice(0,4)} • ★ {item.vote_average?.toFixed(1)}</p></a>; }
function MovieDetail() { const { id } = useParams(); const [data, setData] = useState(null); const [err, setErr] = useState(''); useEffect(()=>{ fetchJSON('/movie/'+id+'?append_to_response=credits,videos,recommendations').then(d=>setData(d)).catch(e=>setErr('Failed to load')); }, [id]); if(err) return <div style={{color:'var(--error)'}}>{err}</div>; if(!data) return <div style={{color:'var(--muted)'}}>Loading…</div>; const trailer = data.videos?.results?.find(v=>v.type==='Trailer' && v.site==='YouTube'); return <div><img src={imgUrl(data.backdrop_path,'w1280')} alt={data.title} style={{width:'100%',maxHeight:420,objectFit:'cover',borderRadius:16,marginBottom:16}} /><div style={{display:'grid',gridTemplateColumns:'280px 1fr',gap:24,alignItems:'start'}}><img src={imgUrl(data.poster_path,'w500')} alt={data.title} style={{borderRadius:12}} /><div><h1 style={{fontSize:28,fontWeight:800}}>{data.title}</h1><p style={{color:'var(--muted)',margin:'8px 0'}}>{data.release_date?.slice(0,4)} • {data.runtime} min • ★ {data.vote_average?.toFixed(1)}</p><div style={{display:'flex',gap:8,flexWrap:'wrap',margin:'12px 0'}}>{data.genres?.map(g=> <span key={g.id} style={{padding:'4px 10px',borderRadius:20,border:'1px solid var(--border)',fontSize:12}}>{g.name}</span>)}</div><p style={{lineHeight:1.7,color:'#ccc'}}>{data.overview}</p>{trailer ? <div style={{marginTop:16}}><iframe width='100%' height='315' src={'https://www.youtube.com/embed/'+trailer.key} title={trailer.name} frameBorder='0' allowFullScreen style={{borderRadius:12,border:'1px solid var(--border)'}} /></div> : <p style={{marginTop:16,color:'var(--muted)'}}>No trailer available.</p>}</div></div><section style={{marginTop:32}}><h3 style={{marginBottom:12}}>Cast</h3><div style={{display:'flex',gap:12,overflowX:'auto'}}>{data.credits?.cast?.slice(0,6).map(c=> <div key={c.id} style={{minWidth:100,textAlign:'center'}}><img src={imgUrl(c.profile_path,'w185')||'https://via.placeholder.com/100x150?text=No+Photo'} alt={c.name} style={{width:80,height:120,objectFit:'cover',borderRadius:8}} /><p style={{fontSize:12,marginTop:6,color:'var(--text)'}}>{c.name}</p></div>)}</div></section><section style={{marginTop:32}}><h3>Recommendations</h3><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(140px,1fr))',gap:12}}>{data.recommendations?.results?.slice(0,6).map(r=><Card key={r.id} item={r} />)}</div></section></div>; }
function SearchPage() { const [q, setQ] = useState(''); const [items, setItems] = useState([]); const [loading, setLoading] = useState(false); const [err, setErr] = useState(''); function runSearch(text) { setLoading(true); setErr(''); Promise.all([fetchJSON('/search/movie?query='+encodeURIComponent(text)), fetchJSON('/search/tv?query='+encodeURIComponent(text))]).then(([m,t])=>setItems([...m.results.map(i=>({...i,type:'movie'})), ...t.results.map(i=>({...i,type:'tv'}))])).catch(e=>setErr('Search error')).finally(()=>setLoading(false)); } return <div><h2>Search</h2><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&runSearch(q)} placeholder='Search movies or TV…' style={{padding:10,width:'100%',maxWidth:500,borderRadius:8,border:'1px solid var(--border)',background:'var(--surface)',color:'var(--text)',marginBottom:16}} />{loading && <p style={{color:'var(--muted)'}}>Loading…</p>}{err && <p style={{color:'var(--error)'}}>{err}</p>}<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(160px,1fr))',gap:16}}>{items.map(i=> <Card key={i.id} item={i} type={i.type} />)}</div>{!loading && !items.length && q && <p style={{color:'var(--muted)'}}>No results.</p>}</div>; }
function TVPage() { const [tv, setTv] = useState([]); useEffect(()=>{ fetchJSON('/tv/popular').then(d=>setTv(d.results.slice(0,8))).catch(()=>{}); },[]); return <div><h2>Popular TV</h2><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(160px,1fr))',gap:16}}>{tv.map(t=> <Card key={t.id} item={t} type='tv' />)}</div></div>; }
function useStorage(key, defaultVal) { const [v, setV] = useState(()=>JSON.parse(localStorage.getItem(key)||'[]')); useEffect(()=>localStorage.setItem(key, JSON.stringify(v)), [v]); return [v, setV]; }
function FavoritesPage() { const [fav] = useStorage('cine_favorites', []); return <div><h2>Favorites</h2><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(160px,1fr))',gap:16}}>{fav.map(i=> <Card key={i.id} item={i} />)}</div></div>; }
function WatchlistPage() { const [wl] = useStorage('cine_watchlist', []); return <div><h2>Watchlist</h2><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(160px,1fr))',gap:16}}>{wl.map(i=> <Card key={i.id} item={i} />)}</div></div>; }
export default function App() { const [movies, setMovies] = useState([]); useEffect(()=>{ fetchJSON('/movie/popular').then(d=>setMovies(d.results.slice(0,8))).catch(()=>{}); },[]); return <BrowserRouter><div style={{maxWidth:1280,margin:'0 auto',padding:24}}><nav style={{display:'flex',gap:16,marginBottom:24,alignItems:'center',flexWrap:'wrap'}}><Link to='/'><b style={{fontSize:20,color:'var(--accent)'}}>CineVault</b></Link><Link to='/'>Movies</Link><Link to='/tv'>TV</Link><Link to='/search'>Search</Link><Link to='/favorites'>Favorites</Link><Link to='/watchlist'>Watchlist</Link></nav><Routes><Route path='/' element={<Home movies={movies}/>} /><Route path='/movie/:id' element={<MovieDetail />} /><Route path='/search' element={<SearchPage />} /><Route path='/tv' element={<TVPage />} /><Route path='/favorites' element={<FavoritesPage />} /><Route path='/watchlist' element={<WatchlistPage />} /><Route path='*' element={<h2>Not found</h2>} /></Routes></div></BrowserRouter>; }
function Home({movies}){ return <div><section style={{background:'linear-gradient(to bottom,rgba(11,12,21,0.7),var(--bg))',padding:48,borderRadius:16,marginBottom:32}}><h1 style={{fontSize:42,fontWeight:800}}>Discover great movies</h1><p style={{color:'var(--muted)',marginTop:8}}>Built with TMDB. Modern cinematic discovery.</p></section><section><h2 style={{marginBottom:16}}>Popular Movies</h2><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(160px,1fr))',gap:16}}>{movies.map(m=> <Card key={m.id} item={m} />)}</div></section></div>; }
"""
with open('src/App.jsx','w') as f:
    f.write(c)
print('done')
